import{_ as e,c as t,o,b0 as r}from"./chunks/framework.BWMBvyU7.js";const _=JSON.parse('{"title":"LV580-用户模式和内核模式","description":null,"frontmatter":{"title":"LV580-用户模式和内核模式","date":"2026-05-05T19:59:42.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/Language/c/memory/126d443715a6152edfa52ba1","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-05-05T19:59:42.338Z","fulluuid":"edfa52ba1fcf497e9c35a375637e4f35","useduuid":"edfa52ba1"}},"headers":[],"relativePath":"sdoc/Language/c/memory/126d443715a6152edfa52ba1.md","filePath":"sdoc/01-编程语言/01-C语言/30-内存管理/LV580-用户模式和内核模式.md","lastUpdated":1777987950000}'),l={name:"sdoc/Language/c/memory/126d443715a6152edfa52ba1.md"};function n(i,a,s,d,p,u){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="lv580-用户模式和内核模式" tabindex="-1">LV580-用户模式和内核模式 <a class="header-anchor" href="#lv580-用户模式和内核模式" aria-label="Permalink to &quot;LV580-用户模式和内核模式&quot;">​</a></h1><h2 id="一、-进程的概念" tabindex="-1">一、 进程的概念 <a class="header-anchor" href="#一、-进程的概念" aria-label="Permalink to &quot;一、 进程的概念&quot;">​</a></h2><p>首先我们要解释一个概念——<strong>进程（Process）</strong>。简单来说，一个可执行程序就是一个进程，前面我们使用 C 语言编译生成的程序，运行后就是一个进程。<strong>进程最显著的特点就是拥有独立的地址空间</strong>。</p><p>严格来说，程序是存储在磁盘上的一个文件，是指令和数据的集合，是一个静态的概念；进程是程序加载到内存运行后一系列的活动，是一个动态的概念。</p><p>前面我们在学习地址空间时，一直说&quot;程序的地址空间&quot;，这其实是不严谨的，应该说&quot;进程的地址空间&quot;。一个进程对应一个地址空间，而一个程序可能会创建多个进程。</p><h2 id="二、-内核模式和用户模式" tabindex="-1">二、 内核模式和用户模式 <a class="header-anchor" href="#二、-内核模式和用户模式" aria-label="Permalink to &quot;二、 内核模式和用户模式&quot;">​</a></h2><p>内核空间存放的是操作系统内核代码和数据，是被所有程序共享的，在程序中修改内核空间中的数据不仅会影响操作系统本身的稳定性，还会影响其他程序，这是非常危险的行为，所以操作系统禁止用户程序直接访问内核空间。</p><p>要想访问内核空间，必须借助操作系统提供的 API 函数，执行内核提供的代码，让内核自己来访问，这样才能保证内核空间的数据不会被随意修改，才能保证操作系统本身和其他程序的稳定性。</p><p>用户程序调用系统 API 函数称为<strong>系统调用（System Call）</strong>；发生系统调用时会暂停用户程序，转而执行内核代码（内核也是程序），访问内核空间，这称为<strong>内核模式（Kernel Mode）</strong>。</p><p>用户空间保存的是应用程序的代码和数据，是程序私有的，其他程序一般无法访问。当执行应用程序自己的代码时，称为<strong>用户模式（User Mode）</strong>。</p><p>计算机会经常在内核模式和用户模式之间切换：</p><ul><li>当运行在用户模式的应用程序需要输入输出、申请内存等比较底层的操作时，就必须调用操作系统提供的 API 函数，从而进入内核模式；</li><li>操作完成后，继续执行应用程序的代码，就又回到了用户模式。</li></ul><p>【<strong>总结</strong>】：用户模式就是执行应用程序代码，访问用户空间；内核模式就是执行内核代码，访问内核空间（当然也有权限访问用户空间）。</p><h2 id="三、-为什么要区分两种模式" tabindex="-1">三、 为什么要区分两种模式 <a class="header-anchor" href="#三、-为什么要区分两种模式" aria-label="Permalink to &quot;三、 为什么要区分两种模式&quot;">​</a></h2><p>我们知道，内核最主要的任务是管理硬件，包括显示器、键盘、鼠标、内存、硬盘等，并且内核也提供了接口（也就是函数），供上层程序使用。当程序要进行输入输出、分配内存、响应鼠标等与硬件有关的操作时，必须要使用内核提供的接口。但是用户程序是非常不安全的，内核对用户程序也是充分不信任的，当程序调用内核接口时，内核要做各种校验，以防止出错。</p><p>从 Intel 80386 开始，出于安全性和稳定性的考虑，CPU 可以运行在 ring0 ~ ring3 四个不同的权限级别，也对数据提供相应的四个保护级别。不过 Linux 和 Windows 只利用了其中的两个运行级别：</p><ul><li>一个是内核模式，对应 ring0 级，操作系统的核心部分和设备驱动都运行在该模式下。</li><li>另一个是用户模式，对应 ring3 级，操作系统的用户接口部分（例如 Windows API）以及所有的用户程序都运行在该级别。</li></ul><h2 id="四、-为什么内核和用户程序要共用地址空间" tabindex="-1">四、 为什么内核和用户程序要共用地址空间 <a class="header-anchor" href="#四、-为什么内核和用户程序要共用地址空间" aria-label="Permalink to &quot;四、 为什么内核和用户程序要共用地址空间&quot;">​</a></h2><p>既然内核也是一个应用程序，为何不让它拥有独立的 4GB 地址空间，而是要和用户程序共享、占用有限的内存呢？</p><p>让内核拥有完全独立的地址空间，就是让内核处于一个独立的进程中，这样每次进行系统调用都需要切换进程。切换进程的消耗是巨大的，不仅需要寄存器进栈出栈，还会使 CPU 中的数据缓存失效、MMU 中的页表缓存失效，这将导致内存的访问在一段时间内相当低效。</p><p>而让内核和用户程序共享地址空间，发生系统调用时进行的是模式切换，模式切换仅仅需要寄存器进栈出栈，不会导致缓存失效；现代 CPU 也都提供了快速进出内核模式的指令，与进程切换比起来，效率大大提高了。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',23)])])}const h=e(l,[["render",n]]);export{_ as __pageData,h as default};
